/**
 * Tests
 * {@link BasicAttributeContext#BasicAttributeContext(AttributeContext)}.
 */
@Test
public void testBasicAttributeContextAttributeContext() {
    Set<String> localAttributes = new LinkedHashSet<String>();
    Set<String> cascadedAttributes = new LinkedHashSet<String>();
    localAttributes.add("local1");
    localAttributes.add("local2");
    cascadedAttributes.add("cascaded1");
    cascadedAttributes.add("cascaded2");
    AttributeContext toCopy = createMock(AttributeContext.class);
    expect(toCopy.getLocalAttributeNames()).andReturn(localAttributes);
    expect(toCopy.getLocalAttribute("local1")).andReturn(new Attribute("value1")).anyTimes();
    expect(toCopy.getLocalAttribute("local2")).andReturn(new Attribute("value2")).anyTimes();
    expect(toCopy.getCascadedAttributeNames()).andReturn(cascadedAttributes);
    expect(toCopy.getCascadedAttribute("cascaded1")).andReturn(new Attribute("value3")).anyTimes();
    expect(toCopy.getCascadedAttribute("cascaded2")).andReturn(new Attribute("value4")).anyTimes();
    Attribute templateAttribute = new Attribute("/template.jsp", Expression.createExpression("expression", null), "role1,role2", "template");
    expect(toCopy.getTemplateAttribute()).andReturn(templateAttribute);
    Set<String> roles = new HashSet<String>();
    roles.add("role1");
    roles.add("role2");
    expect(toCopy.getPreparer()).andReturn("my.preparer.Preparer");
    replay(toCopy);
    BasicAttributeContext context = new BasicAttributeContext(toCopy);
    assertEquals("The template has not been set correctly", "/template.jsp", context.getTemplateAttribute().getValue());
    assertEquals("The template expression has not been set correctly", "expression", context.getTemplateAttribute().getExpressionObject().getExpression());
    assertEquals("The roles are not the same", roles, context.getTemplateAttribute().getRoles());
    assertEquals("The preparer has not been set correctly", "my.preparer.Preparer", context.getPreparer());
    Attribute attribute = context.getLocalAttribute("local1");
    assertNotNull("Attribute local1 not found", attribute);
    assertEquals("Attribute local1 has not been set correctly", "value1", attribute.getValue());
    attribute = context.getLocalAttribute("local2");
    assertNotNull("Attribute local2 not found", attribute);
    assertEquals("Attribute local2 has not been set correctly", "value2", attribute.getValue());
    attribute = context.getCascadedAttribute("cascaded1");
    assertNotNull("Attribute cascaded1 not found", attribute);
    assertEquals("Attribute cascaded1 has not been set correctly", "value3", attribute.getValue());
    attribute = context.getCascadedAttribute("cascaded2");
    assertNotNull("Attribute cascaded2 not found", attribute);
    assertEquals("Attribute cascaded2 has not been set correctly", "value4", attribute.getValue());
}

