    child.add(attribute3);
    child.inherit(parent);
    list = child.getValue();
    assertEquals(LIST_SIZE, list.size());
    assertEquals(attribute1, list.get(0));
    assertEquals(attribute2, list.get(1));
    assertEquals(attribute3, list.get(2));
}

